import string

def check_string(input_string):
    if not input_string:
        raise ValueError("Input string cannot be empty")

    if len(input_string) > 1000000:
        raise ValueError("Input string is too large")

    uppercase_count = 0
    has_lowercase = False
    has_digit = False
    has_special = False

    for char in input_string:
