            uppercase_count += 1
        elif char.islower():
            has_lowercase = True
        elif char.isdigit():
            has_digit = True
        elif char in string.punctuation:
            has_special = True

    if not (has_lowercase and has_digit and has_special):
        return False

    return uppercase_count
