        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def has_three_distinct_prime_factors(n):
    """Check if a number has exactly three distinct prime factors."""
    if n < 2:
        return False

    factors = set()
    temp = n

    # Check for 2
    if temp % 2 == 0:
        factors.add(2)
        while temp % 2 == 0:
            temp //= 2

    # Check for odd factors
    i = 3
    while i * i <= temp:
        if temp % i == 0:
