```python
def sum_non_prime_proper_divisors(n):
    if not isinstance(n, int) or n <= 0:
        raise ValueError("Input must be a positive integer")

    if n == 1:
        return 0

    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True

    total = 0
    for i in range(1, int(n ** 0.5) + 1):
        if n % i == 0:
            if i != n:
                if not is_prime(i):
                    total += i
            if i != n // i and n // i != n:
                if not is_prime(n // i):
                    total += n // i

    return total
```

