## ✅ Function Implementation

```javascript
function swapNestedArrayElements(arr, index1, index2) {
    // Validate input parameters
    if (!Array.isArray(arr)) {
        throw new Error("Input must be an array.");
    }

    if (typeof index1 !== 'number' || typeof index2 !== 'number') {
        throw new Error("Indices must be numbers.");
    }

    if (index1 < 0 || index1 >= arr.length || index2 < 0 || index2 >= arr.length) {
        throw new Error("Indices are out of bounds.");
    }

    if (index1 === index2) {
        // No change needed
        return deepCopy(arr);
    }

    // Create a deep copy of the array to avoid modifying the original
    const result = deepCopy(arr);

    // Swap the elements at the given indices
    [result[index1], result[index2]] = [result[index2], result[index1]];

    return result;
}

// Helper function to perform a deep copy of the array
function deepCopy(arr) {
    if (!Array.isArray(arr)) return arr;

    const copy = Array.isArray(arr) ? [] : arr;

    for (let i = 0; i < arr.length; i++) {
        if (Array.isArray(arr[i])) {
            copy[i] = deepCopy(arr[i]);
        } else {
            copy[i] = arr[i];
        }
    }

    return copy;
}
```

