### ✅ Final Code:

```javascript
// Given number
let number = 10;

// Function to check if a number is prime
function isPrime(n) {
    if (n <= 1) return false;
    if (n === 2) return true;
    if (n % 2 === 0) return false;

    for (let i = 3; i <= Math.sqrt(n); i += 2) {
        if (n % i === 0) return false;
    }
    return true;
}

// Function to validate input
function validateInput(input) {
    // Check if input is a number
    if (typeof input !== 'number') {
        return 'Error: Input is not a number.';
    }

    // Check if it's an integer
    if (!Number.isInteger(input)) {
        return 'Error: Input is not an integer.';
    }

    // Check if it's within the range [1, 100]
    if (input < 1 || input > 100) {
        return `Error: Number must be between 1 and 100. You entered: ${input}.`;
    }

    return null; // No error
}

// Main logic
function main() {
    const error = validateInput(number);

    if (error) {
        console.log(error);
    } else {
        const isPrimeResult = isPrime(number);
        const message = isPrimeResult
            ? `The number ${number} is a prime number.`
            : `The number ${number} is not a prime number.`;
        console.log(message);
    }
}

// Run the main function
main();
```

