            {}
        )

    def test_one_array(self):
        self.assertEqual(
            count_common_elements([1, 2, 3]),
            {}
        )

    def test_all_elements_common(self):
        self.assertEqual(
            count_common_elements([1, 2, 3], [1, 2, 3], [1, 2, 3]),
            {1: 3, 2: 3, 3: 3}
        )

    def test_negative_numbers(self):
