### ✅ **Python Class: `Person`**

```python
import re
from datetime import datetime, timedelta
from typing import List, Dict, Optional, Union

class Person:
    MAX_HOBBIES = 10
    MAX_ADDRESSES = 5
    MAX_NAME_LENGTH = 50
    MAX_STREET_LENGTH = 50
    MAX_CITY_LENGTH = 50
    MAX_STATE_LENGTH = 50
    MAX_ZIP_LENGTH = 5
    MAX_FULL_ADDRESS_LENGTH = 200

    def __init__(self, name: str, age: int, address: Dict[str, str]):
        self.name = name
        self.age = age
        self.addresses = [address]
        self.hobbies: List[str] = []
        self._validate_name(name)
        self._validate_age(age)
        self._validate_address(address)

    def _validate_name(self, name: str):
        if not name or len(name) > self.MAX_NAME_LENGTH:
            raise ValueError(f"Name must be between 1 and {self.MAX_NAME_LENGTH} characters.")
        if not re.match(r'^[A-Za-z\s]+$', name):
            raise ValueError("Name must contain only letters and spaces.")

    def _validate_age(self, age: int):
        if not isinstance(age, int) or age <= 0:
            raise ValueError("Age must be a positive integer.")

    def _validate_address(self, address: Dict[str, str]):
        required_fields = ['street', 'house_number', 'city', 'state', 'zip_code']
        for field in required_fields:
            if field not in address:
                raise ValueError(f"Missing required address field: {field}")

        self._validate_street(address['street'])
        self._validate_house_number(address['house_number'])
        self._validate_city(address['city'])
        self._validate_state(address['state'])
        self._validate_zip_code(address['zip_code'])

    def _validate_street(self, street: str):
        if not street or len(street) > self.MAX_STREET_LENGTH:
            raise ValueError(f"Street must be between 1 and {self.MAX_STREET_LENGTH} characters.")
        if not re.match(r'^[A-Za-z\s]+$', street):
            raise ValueError("Street must contain only letters and spaces.")

    def _validate_house_number(self, house_number: str):
        if not house_number or not re.match(r'^\d+$', house_number):
            raise ValueError("House number must be a positive integer.")

    def _validate_city(self, city: str):
        if not city or len(city) > self.MAX_CITY_LENGTH:
            raise ValueError(f"City must be between 1 and {self.MAX_CITY_LENGTH} characters.")
        if not re.match(r'^[A-Za-z\s]+$', city):
            raise ValueError("City must contain only letters and spaces.")

    def _validate_state(self, state: str):
        if not state or len(state) > self.MAX_STATE_LENGTH:
            raise ValueError(f"State must be between 1 and {self.MAX_STATE_LENGTH} characters.")
        if not re.match(r'^[A-Za-z\s]+$', state):
            raise ValueError("State must contain only letters and spaces.")

    def _validate_zip_code(self, zip_code: str):
        if not zip_code or len(zip_code) != self.MAX_ZIP_LENGTH:
            raise ValueError(f"Zip code must be exactly {self.MAX_ZIP_LENGTH} digits.")
        if not re.match(r'^\d+$', zip_code):
            raise ValueError("Zip code must be a 5-digit number.")

    def _validate_hobbies(self, hobbies: List[str]):
        if not hobbies or len(hobbies) > self.MAX_HOBBIES:
            raise ValueError(f"Maximum of {self.MAX_HOBBIES} hobbies allowed.")
        for hobby in hobbies:
            if not hobby or not re.match(r'^[A-Za-z\s]+$', hobby):
                raise ValueError("Hobbies must contain only letters and spaces.")

    def add_hobby(self, hobby: str):
        self._validate_hobbies([hobby])
        self.hobbies.append(hobby)

    def remove_hobby(self, hobby: str):
        if hobby in self.hobbies:
            self.hobbies.remove(hobby)
        else:
            raise ValueError(f"Hobby '{hobby}' not found.")

    def get_hobbies(self) -> List[str]:
        return self.hobbies

    def get_age_in_months(self) -> int:
        if not isinstance(self.age, int) or self.age <= 0:
            raise ValueError("Age must be a positive integer.")
        birth_date = datetime.now() - timedelta(days=self.age * 365.25)
        birth_year = birth_date.year
        birth_month = birth_date.month
        birth_day = birth_date.day

        # Adjust for leap years
        if birth_day > 28 and birth_month == 2:
            birth_day = 28

        birth_date = datetime(birth_year, birth_month, birth_day)
        current_date = datetime.now()
        months = (current_date.year - birth_date.year) * 12 + (current_date.month - birth_date.month)
        if current_date.day < birth_date.day:
            months -= 1
        return months

    def _validate_age_in_months(self, months: int):
        if not isinstance(months, int) or months <= 0:
            raise ValueError("Age in months must be a positive integer.")

    def get_birth_year(self) -> int:
        if not isinstance(self.age, int) or self.age <= 0:
            raise ValueError("Age must be a positive integer.")
        birth_date = datetime.now() - timedelta(days=self.age * 365.25)
        return birth_date.year

    def _validate_birth_year(self, year: int):
        if not isinstance(year, int) or len(str(year)) != 4:
            raise ValueError("Birth year must be a 4-digit number.")

    def get_full_address(self, address_index: int = 0) -> str:
        if address_index >= len(self.addresses):
            raise IndexError("Address index out of range.")
        address = self.addresses[address_index]
        full_address = (
            f"{address['street']}, {address['house_number']}, "
            f"{address['city']}, {address['state']}, {address['zip_code']}"
        )
        self._validate_full_address(full_address)
        return full_address

    def _validate_full_address(self, address: str):
        if len(address) > self.MAX_FULL_ADDRESS_LENGTH:
            raise ValueError(f"Full address must be at most {self.MAX_FULL_ADDRESS_LENGTH} characters.")
        if not re.match(r'^[A-Za-z0-9\s,]+$', address):
            raise ValueError("Full address must contain only letters, numbers, and spaces.")

    def add_address(self, address: Dict[str, str]):
        if len(self.addresses) >= self.MAX_ADDRESSES:
            raise ValueError(f"Maximum of {self.MAX_ADDRESSES} addresses allowed.")
        self._validate_address(address)
        self.addresses.append(address)

    def remove_address(self, address_index: int):
        if address_index >= len(self.addresses):
            raise IndexError("Address index out of range.")
        self.addresses.pop(address_index)

    def get_address(self, address_index: int) -> Dict[str, str]:
        if address_index >= len(self.addresses):
            raise IndexError("Address index out of range.")
        return self.addresses[address_index]

    def search_hobby(self, hobby: str, case_sensitive: bool = False) -> bool:
        if not hobby:
            return False
        if case_sensitive:
            return hobby in self.hobbies
        else:
            return any(hobby.lower() in h.lower() for h in self.hobbies)

    def display_data(self):
        print(f"Name: {self.name}")
        print(f"Age: {self.age}")
        print(f"Birth Year: {self.get_birth_year()}")
        print(f"Age in Months: {self.get_age_in_months()}")
        print("Hobbies:")
        for hobby in self.hobbies:
            print(f" - {hobby}")
        print("Addresses:")
        for i, address in enumerate(self.addresses):
            print(f"Address {i + 1}:")
            for key, value in address.items():
                print(f"  {key}: {value}")
        print("Full Address (first):")
        print(self.get_full_address())

    def get_all_addresses(self) -> List[Dict[str, str]]:
        return self.addresses
