def print_person_details(person):
    if not person:
        print("No details available")
    else:
        name = person.get("name")
        age = person.get("age")
        hobbies = person.get("hobbies")

        if not name:
            print("Name: Not available")
        elif not name.isalpha():
            print("Name: Invalid")
        else:
            print(f"Name: {name}")

        if not isinstance(age, int):
            print("Age: Not available")
        elif age < 0:
            print("Age: Invalid")
        else:
            print(f"Age: {age}")

        if not hobbies:
            print("Hobbies: None")
        elif len(set(hobbies)) != len(hobbies):
            print("Hobbies: Duplicate hobbies found")
        else:
            print(f"Hobbies: {', '.join(hobbies)}")
