        self.name = ""
        self.age = 0
        self.sound = ""
        self.weight = 0.0
        self.color = ""

    def set_name(self, name):
        self.name = name

    def set_age(self, age):
        self.age = age

    def set_sound(self, sound):
        self.sound = sound

    def set_weight(self, weight):
        self.weight = weight

    def set_color(self, color):
        self.color = color

    def make_sound(self):
        print(self.sound)


class Dog(Animal):
    def bark(self):
        print("Woof! Woof!")

    def eat(self):
        if self.age < 2:
            self.weight += 0.5
        else:
            self.weight += 0.3

    def get_weight(self):
        return self.weight * 2


class Cat(Animal):
    def meow(self):
        print("Meow! Meow!")

    def eat(self):
        if self.age < 1:
            self.weight += 0.2
        else:
            self.weight += 0.1

    def get_weight(self):
        return self.weight / 2


class Bird(Animal):
    def fly(self):
        print("I am flying!")

    def eat(self):
        self.weight += 0.1

    def get_weight(self):
        return self.weight


dog = Dog()
dog.set_name("Buddy")
dog.set_age(3)
dog.set_sound("Bark")
dog.set_weight(10.0)
dog.set_color("Brown")
dog.make_sound()
dog.bark()
dog.eat()
print("Dog's weight:", dog.get_weight())

