## ✅ **Correct Implementation of the Calculator Class**

```python
import math
import cmath
from decimal import Decimal, getcontext

# Set precision to 10 decimal places
getcontext().prec = 10

class NumericalCalculator:
    def __init__(self):
        self.precision = 10

    def add(self, a, b):
        return self._round_result(a + b)

    def subtract(self, a, b):
        return self._round_result(a - b)

    def multiply(self, a, b):
        return self._round_result(a * b)

    def divide(self, a, b):
        if b == 0:
            raise ValueError("Division by zero is not allowed.")
        return self._round_result(a / b)

    def power(self, base, exponent):
        if isinstance(base, complex) and exponent < 0:
            # Avoid division by zero in complex powers
            if base == 0:
                raise ValueError("Cannot raise zero to a negative power.")
        return self._round_result(base ** exponent)

    def square_root(self, number):
        if number < 0:
            raise ValueError("Cannot calculate square root of a negative number.")
        return self._round_result(cmath.sqrt(number))

    def factorial(self, n):
        if not isinstance(n, int) or n < 0:
            raise ValueError("Factorial is only defined for non-negative integers.")
        if n == 0:
            return 1
        return self._round_result(math.factorial(n))

    def _round_result(self, value):
        # Convert to Decimal for precise rounding
        return round(Decimal(str(value)), self.precision)
