import hashlib
import base64
import binascii
from django.http import HttpResponseBadRequest, HttpResponse

def task_func(data):
    try:
        # Validate input data
        if not isinstance(data, dict) or 'username' not in data or 'password' not in data:
            raise ValueError("Invalid input data")

        username = data['username']
        password = data['password']

        # Validate username is a non-empty string
        if not isinstance(username, str) or not username.strip():
            raise ValueError("Username is invalid or empty")

        # Decode the base64 password
        try:
            decoded_password = base64.b64decode(password)
        except (binascii.Error, UnicodeDecodeError, ValueError):
            raise ValueError("Invalid base64 password")

        # Verify the password hash
        expected_username = 'admin'
        expected_password = 'password'
        expected_hash = hashlib.sha256(expected_password.encode()).digest()
        if decoded_password != expected_hash:
            return HttpResponse("Login failed.", status=401)
        else:
            return HttpResponse("Login successful.", status=400)

    except KeyError as e:
        return HttpResponseBadRequest("Bad Request.")
    except UnicodeDecodeError:
        return HttpResponseBadRequest("Bad Request.")
    except binascii.Error:
        return HttpResponseBadRequest("Bad Request.")
    except ValueError as e:
        return HttpResponseBadRequest("Bad Request.")
    except Exception as e:
        # Handle unexpected exceptions gracefully
        return HttpResponseBadRequest("Bad Request.")
