### ✅ **Implementation**

```python
import math
import re
import sys
import readline

class Runtime:
    def __init__(self):
        self.variables = {}
        self.functions = {}
        self.built_in_functions = {
            'sin': math.sin,
            'cos': math.cos,
            'tan': math.tan,
            'asin': math.asin,
            'acos': math.acos,
            'atan': math.atan
        }

    def execute(self, line):
        line = line.strip()
        if not line:
            return

        # Handle exit command
        if line == 'exit()':
            print("Exiting shell.")
            sys.exit()

        # Handle list commands
        if line == 'list_vars':
            self.list_vars()
            return
        if line == 'list_funcs':
            self.list_funcs()
            return

        # Split into tokens
        tokens = self.tokenize(line)
        if not tokens:
            return

        # Parse and evaluate
        try:
            result = self.parse_and_evaluate(tokens)
            print(f"Result: {result}")
        except Exception as e:
            print(f"Error: {e}")

    def tokenize(self, line):
        # Tokenize the input line
        tokens = []
        i = 0
        while i < len(line):
            if line[i].isspace():
                i += 1
            elif line[i] in '+-*/()':
                tokens.append(line[i])
                i += 1
            elif line[i] == '=':
                tokens.append('=')
                i += 1
            elif line[i] == ':':
                tokens.append(':')
                i += 1
            elif line[i] == ',':
                tokens.append(',')
                i += 1
            elif line[i].isalpha():
                # Read identifier
                j = i
                while j < len(line) and line[j].isalnum() or line[j] == '_':
                    j += 1
                tokens.append(line[i:j])
                i = j
            elif line[i].isdigit() or line[i] == '.':
                # Read number
                j = i
                while j < len(line) and (line[j].isdigit() or line[j] == '.'):
                    j += 1
                tokens.append(line[i:j])
                i = j
            else:
                # Unknown character
                raise ValueError(f"Unknown character: {line[i]}")
        return tokens

    def parse_and_evaluate(self, tokens):
        # Parse and evaluate the tokens
        if tokens[0] == 'def':
            return self.parse_function_definition(tokens)
        elif tokens[0] == 'var':
            return self.parse_variable_assignment(tokens)
        else:
            return self.parse_expression(tokens)

    def parse_function_definition(self, tokens):
        # Parse function definition: def <name>(<params>): <body>
        if len(tokens) < 6 or tokens[1] != '(' or tokens[5] != ')':
            raise ValueError("Invalid function definition syntax")

        name = tokens[2]
        params = self.parse_parameters(tokens[3:-3])
        body = self.parse_expression(tokens[6:])

        # Check for duplicate function name
        if name in self.functions:
            raise ValueError(f"Function '{name}' already defined")

        # Check for duplicate parameter names
        if len(params) != len(set(params)):
            raise ValueError("Duplicate parameter names in function definition")

        self.functions[name] = (params, body)
        return f"Function '{name}' defined with parameters {params}"

    def parse_parameters(self, params_str):
        # Parse parameters from a string like "x,y"
        if not params_str:
            return []
        return params_str.split(',')

    def parse_variable_assignment(self, tokens):
        # Parse variable assignment: var <name> = <expr>
        if len(tokens) < 4 or tokens[1] != '=':
            raise ValueError("Invalid variable assignment syntax")

        name = tokens[2]
        expr_tokens = tokens[4:]

        # Evaluate the expression
        value = self.parse_expression(expr_tokens)
        self.variables[name] = value
        return f"Variable '{name}' assigned value {value}"

    def parse_expression(self, tokens):
        # Parse and evaluate an arithmetic expression
        # This is a simple recursive descent parser
        return self.parse_add_sub(tokens)

    def parse_add_sub(self, tokens):
        # Parse addition and subtraction
        left = self.parse_mul_div(tokens)
        while tokens and tokens[0] in ('+', '-'):
            op = tokens.pop(0)
            right = self.parse_mul_div(tokens)
            left = self.evaluate_binary_op(left, op, right)
        return left

    def parse_mul_div(self, tokens):
        # Parse multiplication and division
        left = self.parse_unary(tokens)
        while tokens and tokens[0] in ('*', '/'):
            op = tokens.pop(0)
            right = self.parse_unary(tokens)
            left = self.evaluate_binary_op(left, op, right)
        return left

    def parse_unary(self, tokens):
        # Parse unary minus
        if tokens and tokens[0] == '-':
            tokens.pop(0)
            return -self.parse_unary(tokens)
        return self.parse_parentheses(tokens)

    def parse_parentheses(self, tokens):
        # Parse parentheses
        if tokens and tokens[0] == '(':
            tokens.pop(0)
            expr = self.parse_expression(tokens)
            if tokens and tokens[0] == ')':
                tokens.pop(0)
            else:
                raise ValueError("Mismatched parentheses")
            return expr
        return self.parse_number_or_variable(tokens)

    def parse_number_or_variable(self, tokens):
        # Parse a number or variable
        if not tokens:
            raise ValueError("Unexpected end of input")
        token = tokens[0]
        if token in self.variables:
            tokens.pop(0)
            return self.variables[token]
        elif token in self.functions:
            # Function call
            tokens.pop(0)
            if tokens[0] != '(':
                raise ValueError("Function call must be followed by '('")
            tokens.pop(0)
            args = self.parse_function_arguments(tokens)
            if tokens and tokens[0] == ')':
                tokens.pop(0)
            else:
                raise ValueError("Mismatched parentheses")
            return self.evaluate_function_call(token, args)
        elif token.replace('.', '', 1).isdigit():
            tokens.pop(0)
            return float(token)
        else:
            raise ValueError(f"Unknown token: {token}")

    def parse_function_arguments(self, tokens):
        # Parse function arguments
        args = []
        while tokens and tokens[0] != ')':
            arg = self.parse_number_or_variable(tokens)
            args.append(arg)
            if tokens and tokens[0] == ',':
                tokens.pop(0)
        return args

    def evaluate_function_call(self, func_name, args):
        # Evaluate a function call
        if func_name in self.built_in_functions:
            return self.built_in_functions[func_name](*args)
        elif func_name in self.functions:
            func_params, func_body = self.functions[func_name]
            if len(args) != len(func_params):
                raise ValueError(f"Function '{func_name}' expects {len(func_params)} arguments, got {len(args)}")
            # Substitute parameters with arguments
            scope = dict(zip(func_params, args))
            return self.evaluate_expression(func_body, scope)
        else:
            raise ValueError(f"Undefined function: {func_name}")

    def evaluate_expression(self, tokens, scope):
        # Evaluate an expression in a given scope
        return self.parse_expression(tokens)

    def evaluate_binary_op(self, left, op, right):
        # Evaluate binary operations
        if op == '+':
            return left + right
        elif op == '-':
            return left - right
        elif op == '*':
            return left * right
        elif op == '/':
            if right == 0:
                raise ValueError("Division by zero")
            return left / right
        else:
            raise ValueError(f"Unknown operator: {op}")

    def list_vars(self):
        # List all defined variables
        if not self.variables:
            print("No variables defined.")
        else:
            print("Defined variables:")
            for name, value in self.variables.items():
                print(f"  {name} = {value}")

    def list_funcs(self):
        # List all defined functions
        if not self.functions:
            print("No functions defined.")
        else:
            print("Defined functions:")
            for name, (params, body) in self.functions.items():
                print(f"  {name}({', '.join(params)}) = {body}")

    def start_shell(self):
        print("Welcome to the Math Shell. Type 'exit()' to exit.")
        print("Type 'list_vars' or 'list_funcs' to list variables or functions.")
        print("Use 'var x = 3.5' to assign variables, 'def f(x,y):x+y' to define functions.")
        print("Enter expressions to evaluate.")
        while True:
            try:
                line = input(">>> ")
                self.execute(line)
            except KeyboardInterrupt:
                print("\nExiting shell.")
                sys.exit()
            except EOFError:
                print("\nExiting shell.")
                sys.exit()

# Run the shell
if __name__ == "__main__":
    runtime = Runtime()
    runtime.start_shell()
