```python
import re
import hashlib
import uuid
from datetime import datetime, timedelta
from typing import Optional, Dict, Any

class User:
    def __init__(self, user_id: str, email: str, password_hash: str, is_verified: bool = False):
        self.user_id = user_id
        self.email = email
        self.password_hash = password_hash
        self.is_verified = is_verified
        self.profile_picture = None
        self.ratings = []

    def verify_password(self, password: str) -> bool:
        return hashlib.sha256(password.encode()).hexdigest() == self.password_hash

    def update_profile_picture(self, picture_url: str) -> bool:
        if re.match(r'^https?://', picture_url):
            self.profile_picture = picture_url
            return True
        return False

    def add_rating(self, rating: float) -> bool:
        if 0 <= rating <= 5:
            self.ratings.append(rating)
            return True
        return False

    def get_average_rating(self) -> float:
        if not self.ratings:
            return 0.0
        return sum(self.ratings) / len(self.ratings)

    def is_verified(self) -> bool:
        return self.is_verified

    def get_email(self) -> str:
        return self.email

    def get_user_id(self) -> str:
        return self.user_id


class AccountPublicView:
    def __init__(self, user: User):
        self.user = user

    def get_public_details(self) -> Dict[str, Any]:
        return {
            "user_id": self.user.get_user_id(),
            "email": self.user.get_email(),
            "is_verified": self.user.is_verified(),
            "profile_picture": self.user.profile_picture,
            "average_rating": self.user.get_average_rating()
        }


class ChangePasswordView:
    def __init__(self, user: User):
        self.user = user

    def change_password(self, old_password: str, new_password: str) -> bool:
        if not self.user.verify_password(old_password):
            return False
        if len(new_password) < 8:
            return False
        self.user.password_hash = hashlib.sha256(new_password.encode()).hexdigest()
        return True


class Login:
    def __init__(self, users: Dict[str, User]):
        self.users = users

    def login(self, email: str, password: str) -> Optional[User]:
        user = self.users.get(email)
        if user and user.verify_password(password):
            return user
        return None


class Logout:
    def __init__(self, session: Dict[str, User]):
        self.session = session

    def logout(self) -> bool:
        if self.session:
            self.session.clear()
            return True
        return False


class RegistrationView:
    def __init__(self, users: Dict[str, User]):
        self.users = users

    def register(self, email: str, password: str) -> Optional[str]:
        if not re.match(r'^[\w\.-]+@[\w\.-]+\.\w+$', email):
            return "Invalid email format"
        if email in self.users:
            return "Email already exists"
        if len(password) < 8:
            return "Password must be at least 8 characters"
        user_id = str(uuid.uuid4())
        user = User(user_id, email, hashlib.sha256(password.encode()).hexdigest())
        self.users[email] = user
        return user_id


class VerifyEmail:
    def __init__(self, users: Dict[str, User]):
        self.users = users

    def verify(self, email: str) -> bool:
        user = self.users.get(email)
        if not user:
            return False
        user.is_verified = True
        return True


class AccountPropertiesView:
    def __init__(self, user: User):
        self.user = user

    def get_properties(self) -> Dict[str, Any]:
        return {
            "user_id": self.user.get_user_id(),
            "email": self.user.get_email(),
            "is_verified": self.user.is_verified(),
            "profile_picture": self.user.profile_picture
        }

    def update_properties(self, email: str, profile_picture: str) -> bool:
        if email and re.match(r'^[\w\.-]+@[\w\.-]+\.\w+$', email):
            self.user.email = email
        if profile_picture and re.match(r'^https?://', profile_picture):
            self.user.profile_picture = profile_picture
        return True


class UpdateAccountPicture:
    def __init__(self, user: User):
        self.user = user

    def update(self, picture_url: str) -> bool:
        if re.match(r'^https?://', picture_url):
            self.user.profile_picture = picture_url
            return True
        return False


class RatingView:
    def __init__(self, user: User):
        self.user = user

    def get_ratings(self) -> list:
        return self.user.ratings

    def get_average_rating(self) -> float:
        return self.user.get_average_rating()


class PostRatingView:
    def __init__(self, user: User):
        self.user = user

    def post_rating(self, rating: float) -> bool:
        if 0 <= rating <= 5:
            self.user.add_rating(rating)
            return True
        return False


class LoggedInRatingView:
    def __init__(self, user: User):
        self.user = user

    def get_ratings(self) -> list:
        return self.user.ratings

    def get_average_rating(self) -> float:
        return self.user.get_average_rating()

    def post_rating(self, rating: float) -> bool:
        if 0 <= rating <= 5:
            self.user.add_rating(rating)
            return True
        return False
