import unittest
from user_account_management import (
    User,
    AccountPublicView,
    ChangePasswordView,
    Login,
    Logout,
    RegistrationView,
    VerifyEmail,
    AccountPropertiesView,
    UpdateAccountPicture,
    RatingView,
    PostRatingView,
    LoggedInRatingView
)

class TestUserAccountManagement(unittest.TestCase):
    def setUp(self):
        self.users = {}
        self.user = User(
            user_id="12345",
            email="test@example.com",
            password_hash=hashlib.sha256("password123".encode()).hexdigest()
        )
        self.users["test@example.com"] = self.user

    def test_registration(self):
        # Positive case
        result = RegistrationView(self.users).register("newuser@example.com", "password123")
        self.assertIsNotNone(result)
        self.assertIn("newuser@example.com", self.users)

        # Negative case: invalid email
        result = RegistrationView(self.users).register("invalidemail", "password123")
        self.assertEqual(result, "Invalid email format")

        # Negative case: email already exists
        result = RegistrationView(self.users).register("test@example.com", "password123")
        self.assertEqual(result, "Email already exists")

        # Negative case: password too short
        result = RegistrationView(self.users).register("another@example.com", "pass")
        self.assertEqual(result, "Password must be at least 8 characters")

    def test_login(self):
        # Positive case
        user = Login(self.users).login("test@example.com", "password123")
        self.assertIsNotNone(user)

        # Negative case: invalid password
        user = Login(self.users).login("test@example.com", "wrongpassword")
        self.assertIsNone(user)

        # Negative case: user not found
        user = Login(self.users).login("nonexistent@example.com", "password123")
        self.assertIsNone(user)

    def test_logout(self):
        session = {"user": self.user}
        logout = Logout(session)
        self.assertTrue(logout.logout())
        self.assertEqual(session, {})

    def test_change_password(self):
        view = ChangePasswordView(self.user)
        self.assertTrue(view.change_password("password123", "newpassword123"))
        self.assertFalse(view.change_password("password123", "short"))
        self.assertFalse(view.change_password("wrongpassword", "newpassword123"))

    def test_account_public_view(self):
        view = AccountPublicView(self.user)
        public_details = view.get_public_details()
        self.assertEqual(public_details["email"], "test@example.com")
        self.assertEqual(public_details["is_verified"], False)
        self.assertEqual(public_details["average_rating"], 0.0)

    def test_account_properties_view(self):
        view = AccountPropertiesView(self.user)
        properties = view.get_properties()
        self.assertEqual(properties["email"], "test@example.com")
        self.assertEqual(properties["is_verified"], False)
        self.assertEqual(properties["profile_picture"], None)

        view.update_properties("newemail@example.com", "https://example.com/pic.jpg")
        updated_properties = view.get_properties()
        self.assertEqual(updated_properties["email"], "newemail@example.com")
        self.assertEqual(updated_properties["profile_picture"], "https://example.com/pic.jpg")

    def test_update_account_picture(self):
        view = UpdateAccountPicture(self.user)
        self.assertTrue(view.update("https://example.com/pic.jpg"))
        self.assertEqual(view.user.profile_picture, "https://example.com/pic.jpg")
        self.assertFalse(view.update("invalid_url"))

    def test_verify_email(self):
        view = VerifyEmail(self.users)
        self.assertTrue(view.verify("test@example.com"))
        self.assertEqual(self.users["test@example.com"].is_verified, True)

    def test_rating_views(self):
        view = RatingView(self.user)
        self.assertEqual(view.get_ratings(), [])
        self.assertEqual(view.get_average_rating(), 0.0)

        post_view = PostRatingView(self.user)
        self.assertTrue(post_view.post_rating(4.5))
        self.assertTrue(post_view.post_rating(3.0))
        self.assertEqual(self.user.get_average_rating(), 3.75)

        logged_in_view = LoggedInRatingView(self.user)
        self.assertEqual(logged_in_view.get_ratings(), [4.5, 3.0])
        self.assertEqual(logged_in_view.get_average_rating(), 3.75)
        self.assertTrue(logged_in_view.post_rating(5.0))
        self.assertEqual(logged_in_view.get_average_rating(), 4.375)

if __name__ == "__main__":
