    classifier.fit(X, y)
    predictions = classifier.predict(X)

    assert isinstance(predictions, pd.Series)
    assert len(predictions) == len(y)

    score = classifier.score(X, y)
    assert isinstance(score, float)
    assert score >= 0.0 and score <= 1.0

