### 📜 Lambda Function Code

```python
import json
import boto3
from aws_lambda_powertools import Logger, Tracer, Metrics
from aws_lambda_powertools.logging import log_event
from aws_lambda_powertools.metrics import metric
from aws_lambda_powertools.tracing import trace
from aws_lambda_powertools.exceptions import LambdaException
from botocore.exceptions import ClientError

# Initialize Logger, Tracer, and Metrics
logger = Logger()
tracer = Tracer()
metrics = Metrics()

# Set up S3 client
s3_client = boto3.client('s3')

@logger.inject_lambda_context
@tracer.capture_lambda_handler
@metrics.log_metrics
def lambda_handler(event, context):
    try:
        # Parse the S3 event
        records = event.get('Records', [])
        if not records:
            logger.error("No records found in the event")
            return {"error": "No records found in the event"}

        # Process each record
        for record in records:
            bucket_name = record['s3']['bucket']['name']
            object_key = record['s3']['object']['key']

            # Retrieve the object from S3
            try:
                response = s3_client.get_object(Bucket=bucket_name, Key=object_key)
                content = response['Body'].read().decode('utf-8')
                logger.info(f"Retrieved content from {bucket_name}/{object_key}")
                logger.info(f"Content: {content}")

                # Log the event details
                logger.info(f"Event: {json.dumps(record, indent=2)}")

                # Record a custom metric
                metrics.add_metric(name="S3ObjectProcessed", unit="Count", value=1)

            except ClientError as e:
                if e.response['Error']['Code'] == '404':
                    logger.error(f"Object {object_key} not found in bucket {bucket_name}")
                else:
                    logger.error(f"Error retrieving object {object_key}: {e}")
                return {"error": f"Error retrieving object {object_key}: {e}"}

            except UnicodeDecodeError:
                logger.error(f"Failed to decode content of {object_key} as UTF-8")
                return {"error": f"Failed to decode content of {object_key} as UTF-8"}

            except Exception as e:
                logger.error(f"Unexpected error: {e}")
                return {"error": f"Unexpected error: {e}"}

        return {
            "content": content,
            "event": event,
            "status": "success"
        }

    except Exception as e:
        logger.error(f"Unexpected error in Lambda handler: {e}")
        return {"error": f"Unexpected error in Lambda handler: {e}"}
```

