        day = get_object_or_404(DayName, pk=day_name)

        RecipePlan.objects.create(
            meal_name=meal_name,
            recipe=recipe,
            plan=plan,
            order=meal_number,
            day_name=day
        )
        return redirect(f'/plan/{plan.id}/')

