Here's a comprehensive implementation of the `DynamoDBSessionStore` class in Python, along with unit tests using `unittest` and `boto3`. This class provides a clean, modular interface for managing sessions using Amazon DynamoDB as the backend.

---

## ✅ **DynamoDBSessionStore Class Implementation**

```python
import boto3
import json
import base64
from botocore.exceptions import ClientError
import os
import unittest
from unittest.mock import patch, MagicMock

class DynamoDBSessionStore:
    def __init__(self, table_name, region_name='us-west-2'):
        self.table_name = table_name
        self.region_name = region_name
        self.dynamodb = boto3.resource('dynamodb', region_name=region_name)
        self.table = self.dynamodb.Table(table_name)

    def _validate_session_key(self, session_key):
        if not isinstance(session_key, str) or len(session_key) < 1:
            raise ValueError("Session key must be a non-empty string.")

    def _validate_session_data(self, session_data):
        if not isinstance(session_data, dict):
            raise ValueError("Session data must be a dictionary.")

    def _encrypt_data(self, data):
        """Encrypt session data using base64 encoding (for demonstration)."""
        return base64.b64encode(json.dumps(data).encode('utf-8')).decode('utf-8')

    def _decrypt_data(self, encrypted_data):
        """Decrypt session data using base64 decoding."""
        return json.loads(base64.b64decode(encrypted_data).decode('utf-8'))

    def _get_item(self, session_key):
        try:
            response = self.table.get_item(Key={'session_key': session_key})
            return response.get('Item', None)
        except ClientError as e:
            raise RuntimeError(f"Error retrieving session: {e}") from e

    def _put_item(self, session_key, session_data):
        try:
            self.table.put_item(
                Item={
                    'session_key': session_key,
                    'session_data': self._encrypt_data(session_data)
                }
            )
        except ClientError as e:
            raise RuntimeError(f"Error creating session: {e}") from e

    def _delete_item(self, session_key):
        try:
            self.table.delete_item(Key={'session_key': session_key})
        except ClientError as e:
            if e.response['Error']['Code'] == 'ResourceNotFoundException':
                raise RuntimeError(f"Session not found: {session_key}") from e
            else:
                raise RuntimeError(f"Error deleting session: {e}") from e

    def load_session(self, session_key):
        self._validate_session_key(session_key)
        item = self._get_item(session_key)
        if not item:
            return None
        return self._decrypt_data(item['session_data'])

    def session_exists(self, session_key):
        self._validate_session_key(session_key)
        return self._get_item(session_key) is not None

    def create_session(self, session_key, session_data):
        self._validate_session_key(session_key)
        self._validate_session_data(session_data)
        if self.session_exists(session_key):
            raise RuntimeError(f"Session with key '{session_key}' already exists.")
        self._put_item(session_key, session_data)

    def save_session(self, session_key, session_data):
        self._validate_session_key(session_key)
        self._validate_session_data(session_data)
        self._put_item(session_key, session_data)

    def delete_session(self, session_key):
        self._validate_session_key(session_key)
        self._delete_item(session_key)
