class TestDynamoDBSessionStore(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.table_name = "TestSessionTable"
        cls.region_name = "us-west-2"
        cls.dynamodb = boto3.resource('dynamodb', region_name=cls.region_name)
        cls.client = boto3.client('dynamodb', region_name=cls.region_name)

        # Create a test table
        try:
            cls.client.create_table(
                TableName=cls.table_name,
                KeySchema=[{'AttributeName': 'session_key', 'KeyType': 'HASH'}],
                AttributeDefinitions=[{'AttributeName': 'session_key', 'AttributeType': 'S'}],
                ProvisionedThroughput={'ReadCapacityUnits': 5, 'WriteCapacityUnits': 5}
            )
        except ClientError as e:
            if e.response['Error']['Code'] != 'ResourceInUseException':
                raise

    @classmethod
    def tearDownClass(cls):
        # Delete the test table
        try:
            cls.client.delete_table(TableName=cls.table_name)
        except ClientError as e:
            if e.response['Error']['Code'] != 'ResourceNotFoundException':
                raise

    def setUp(self):
        self.store = DynamoDBSessionStore(self.table_name, self.region_name)

    def test_load_session_nonexistent(self):
        self.assertIsNone(self.store.load_session("nonexistent_key"))

    def test_load_session_valid(self):
        self.store.create_session("valid_key", {"user": "test", "logged_in": True})
        session = self.store.load_session("valid_key")
        self.assertEqual(session, {"user": "test", "logged_in": True})

    def test_session_exists_true(self):
        self.store.create_session("exists_key", {"user": "test"})
        self.assertTrue(self.store.session_exists("exists_key"))

    def test_session_exists_false(self):
        self.assertFalse(self.store.session_exists("nonexistent_key"))

    def test_create_session(self):
        self.store.create_session("new_key", {"user": "test"})
        self.assertTrue(self.store.session_exists("new_key"))

    def test_create_session_duplicate(self):
        self.store.create_session("dup_key", {"user": "test"})
        with self.assertRaises(RuntimeError):
            self.store.create_session("dup_key", {"user": "test2"})

    def test_save_session(self):
        self.store.create_session("save_key", {"user": "test"})
        self.store.save_session("save_key", {"user": "test", "updated": True})
        session = self.store.load_session("save_key")
        self.assertEqual(session, {"user": "test", "updated": True})

    def test_delete_session(self):
        self.store.create_session("delete_key", {"user": "test"})
        self.store.delete_session("delete_key")
        self.assertIsNone(self.store.load_session("delete_key"))

    def test_delete_session_nonexistent(self):
        with self.assertRaises(RuntimeError):
            self.store.delete_session("nonexistent_key")

    def test_invalid_session_key(self):
        with self.assertRaises(ValueError):
            self.store.load_session("")

    def test_invalid_session_data(self):
        with self.assertRaises(ValueError):
            self.store.create_session("key", "not a dict")

    def test_encryption_decryption(self):
        data = {"user": "test", "token": "abc123"}
        encrypted = self.store._encrypt_data(data)
        decrypted = self.store._decrypt_data(encrypted)
        self.assertEqual(decrypted, data)

    @patch('boto3.resource')
    def test_connection_failure(self, mock_resource):
        mock_resource.side_effect = Exception("Connection failed")
        with self.assertRaises(Exception):
            DynamoDBSessionStore("invalid_table", "us-west-2")
