```python
import json
import requests
from django.http import JsonResponse, HttpResponse
from django.shortcuts import render
from .forms import WallpaperForm
from .helpers import convert_images

def wallpaper(request):
    if request.method == 'POST':
        form = WallpaperForm(request.POST)
        if form.is_valid():
            search_phrase = form.cleaned_data['search_phrase']
            random = form.cleaned_data['random']
            images = convert_images(search_phrase, random)
            return JsonResponse({'images': images})
    else:
        form = WallpaperForm()
    return render(request, 'home.html', {'form': form})
```

