## 📜 `helpers.py` (In `wallpaper_app`)

```python
import requests
import base64
import time
from urllib.parse import quote

def convert_images(search_phrase, random):
    base_url = "https://wallhaven.cc/api/v1/wallpapers"
    params = {
        'p': 1,
        's': 'top',
        'a': 'all',
        'q': '1920x1080',
        'r': '16x9',
        'categories': 'general',
        'sort': 'top'
    }

    if search_phrase:
        params['q'] = quote(search_phrase)
    if random:
        params['random'] = '1'

    try:
        response = requests.get(base_url, params=params, timeout=10)
        response.raise_for_status()
        data = response.json()
    except requests.RequestException as e:
        return [{'error': 'Failed to fetch wallpapers. Please try again later.'}]

    images = []
    for item in data.get('data', []):
        if not item.get('preview') or not item.get('preview').get('medium'):
            continue
        image_url = item['preview']['medium']
        try:
            image_response = requests.get(image_url, timeout=10)
            image_response.raise_for_status()
            image_data = image_response.content
            image_base64 = base64.b64encode(image_data).decode('utf-8')
            images.append((item['tags'][0], image_base64))
        except requests.RequestException as e:
            continue

    return images
```

