    <meta charset="UTF-8">
    <title>Wallpaper Search</title>
    <script src="https://code.jquery.com/jquery-3.6.0.min.js"></script>
    <style>
        .thumbnail {
            width: 150px;
            height: 100px;
            object-fit: cover;
            margin: 10px;
            border: 1px solid #ccc;
        }
        .loading {
            display: none;
            text-align: center;
            font-weight: bold;
        }
    </style>
</head>
<body>
    <h1>Wallpaper Search</h1>
    <form id="wallpaper-form">
        {{ form.as_p }}
        <button type="submit">Search</button>
    </form>

    <div class="loading" id="loading">Loading...</div>
    <div id="results"></div>

    <script>
        $(document).ready(function () {
            $('#wallpaper-form').on('submit', function (e) {
                e.preventDefault();
                $('#loading').show();
                $('#results').empty();

                $.ajax({
                    url: '/wallpaper/',
                    type: 'POST',
                    data: $('#wallpaper-form').serialize(),
                    success: function (response) {
                        $('#loading').hide();
                        if (response.images && response.images.length > 0) {
                            let html = '';
                            response.images.forEach(function (item) {
                                html += `<img src="data:image/${item[0]};base64,${item[1]}" class="thumbnail" alt="Wallpaper">`;
                            });
                            $('#results').html(html);
                        } else {
                            $('#results').html('<p>No wallpapers found.</p>');
                        }
                    },
                    error: function () {
                        $('#loading').hide();
                        $('#results').html('<p>An error occurred. Please try again.</p>');
                    }
                });
            });
        });
    </script>
</body>
</html>
