## 🧑‍💻 **5. CustomerVerifier Class**

```java
import java.util.ArrayList;
import java.util.List;

public class CustomerVerifier {
    private final List<Verification> verifications;

    public CustomerVerifier(Verification... verifications) {
        this.verifications = new ArrayList<>();
        for (Verification verification : verifications) {
            this.verifications.add(verification);
        }
    }

    public CustomerVerificationResult verify(Customer customer) {
        List<String> failedVerifications = new ArrayList<>();

        for (Verification verification : verifications) {
            try {
                if (!verification.verify(customer)) {
                    failedVerifications.add(verification.getVerificationName());
                }
            } catch (Exception e) {
                // Log the error securely (e.g., using a logging framework)
                // For this example, we'll just log the name of the verification
                failedVerifications.add(verification.getVerificationName() + " failed due to an error");
            }
        }

        return new CustomerVerificationResult(failedVerifications.isEmpty(), failedVerifications);
    }
}
