### ✅ **Implementation**

```python
class Test:
    def __init__(self):
        pass

    def name(self):
        return self.__class__.__name__

    @classmethod
    def description(cls):
        return getattr(cls, 'description', None)


class TestRegistry:
    def __init__(self):
        self._registered_tests = {}

    def register(self, test_class, name=None):
        if not issubclass(test_class, Test):
            raise ValueError("Class must inherit from Test")

        if name is None:
            name = test_class.name()
        elif name in self._registered_tests:
            raise ValueError(f"Test class with name '{name}' already registered")

        self._registered_tests[name] = test_class

    def get(self, name):
        if name not in self._registered_tests:
            raise KeyError(f"Test class with name '{name}' not found")
        return self._registered_tests[name]

    def list_all(self):
        return list(self._registered_tests.keys())
```

