### ✅ **Test Cases**

```python
import unittest

class TestRegistryTest(unittest.TestCase):
    def setUp(self):
        self.registry = TestRegistry()

    def test_register_valid_class(self):
        class MyTest(Test):
            description = "This is a test"

        self.registry.register(MyTest, "MyTest")
        self.assertEqual(self.registry.get("MyTest"), MyTest)
        self.assertIn("MyTest", self.registry.list_all())

    def test_register_same_name_twice(self):
        class MyTest(Test):
            description = "This is a test"

        self.registry.register(MyTest, "MyTest")
        with self.assertRaises(ValueError):
            self.registry.register(MyTest, "MyTest")

    def test_register_non_test_class(self):
        class MyNonTest:
            pass

        with self.assertRaises(ValueError):
            self.registry.register(MyNonTest, "MyNonTest")

    def test_register_with_custom_name(self):
        class MyTest(Test):
            description = "Custom name test"

        self.registry.register(MyTest, "CustomName")
        self.assertEqual(self.registry.get("CustomName"), MyTest)
        self.assertIn("CustomName", self.registry.list_all())

    def test_get_nonexistent_class(self):
        with self.assertRaises(KeyError):
            self.registry.get("NonExistent")

    def test_list_all_registered(self):
        class Test1(Test):
            description = "Test 1"

        class Test2(Test):
            description = "Test 2"

        self.registry.register(Test1, "Test1")
        self.registry.register(Test2, "Test2")
        self.assertEqual(self.registry.list_all(), ["Test1", "Test2"])

    def test_description_method(self):
        class MyTest(Test):
            description = "My Test Description"

        self.registry.register(MyTest, "MyTest")
        self.assertEqual(MyTest.description(), "My Test Description")

    def test_description_not_provided(self):
        class MyTest(Test):
            pass

        self.registry.register(MyTest, "MyTest")
        self.assertIsNone(MyTest.description())

if __name__ == "__main__":
    unittest.main()
```

