import hashlib
import sys
import argparse

class FileDigestComparer:
    def __init__(self, filename):
        self.filename = filename
        self.md5 = self.compute_md5()
        self.sha1 = self.compute_sha1()

    def compute_md5(self):
        """Compute and return the MD5 digest of the file."""
        hash_md5 = hashlib.md5()
        try:
            with open(self.filename, "rb") as f:
                for chunk in iter(lambda: f.read(4096), b""):
                    hash_md5.update(chunk)
        except FileNotFoundError:
            raise FileNotFoundError(f"The file {self.filename} does not exist.")
        return hash_md5.hexdigest()

    def compute_sha1(self):
        """Compute and return the SHA1 digest of the file."""
        hash_sha1 = hashlib.sha1()
        try:
            with open(self.filename, "rb") as f:
                for chunk in iter(lambda: f.read(4096), b""):
                    hash_sha1.update(chunk)
        except FileNotFoundError:
            raise FileNotFoundError(f"The file {self.filename} does not exist.")
        return hash_sha1.hexdigest()

    def compare_digests(self, other):
        """Compare MD5 and SHA1 digests with another FileDigestComparer instance."""
        if not isinstance(other, FileDigestComparer):
            raise TypeError("Argument must be an instance of FileDigestComparer.")
        return self.md5 == other.md5 and self.sha1 == other.sha1

    def __str__(self):
        """Return a string representation of the file's name and its digests."""
        return f"File: {self.filename}\nMD5: {self.md5}\nSHA1: {self.sha1}"

def main():
    parser = argparse.ArgumentParser(description="Compute and compare file digests.")
    subparsers = parser.add_subparsers(dest="command")

    # Subparser for computing digests of a single file
    parser_single = subparsers.add_parser("digest", help="Compute MD5 and SHA1 of a single file.")
    parser_single.add_argument("filename", type=str, help="Path to the file.")

    # Subparser for comparing digests of two files
    parser_compare = subparsers.add_parser("compare", help="Compare digests of two files.")
    parser_compare.add_argument("file1", type=str, help="Path to the first file.")
    parser_compare.add_argument("file2", type=str, help="Path to the second file.")

    args = parser.parse_args()

    if args.command == "digest":
        if not args.filename:
            parser.error("Filename is required for 'digest' command.")
        try:
            file1 = FileDigestComparer(args.filename)
            print(file1)
        except FileNotFoundError as e:
            print(f"Error: {e}")

    elif args.command == "compare":
        if not args.file1 or not args.file2:
            parser.error("Two filenames are required for 'compare' command.")
        try:
            file1 = FileDigestComparer(args.file1)
            file2 = FileDigestComparer(args.file2)
            if file1.compare_digests(file2):
                print("The files have identical MD5 and SHA1 digests.")
            else:
                print("The files have different digests.")
        except FileNotFoundError as e:
            print(f"Error: {e}")

    else:
        parser.print_help()

if __name__ == "__main__":
