@app.route('/ztest', methods=['POST'])
def ztest():
    try:
        data = request.get_json()
        if not data:
            return jsonify({"error": "No data provided."}), 400

        if "samples" in data:
            samples = data["samples"]
            if len(samples) == 1:
                sample = samples[0]
                validate_data(sample)
                # One-sample Z-test
                z_stat, p_value = stats.ztest(sample, value=np.mean(sample), alternative='two-sided')
                return jsonify({
                    "z_statistic": float(z_stat),
                    "p_value": float(p_value),
                    "message": "One-sample Z-test performed."
                })
            elif len(samples) == 2:
                sample1, sample2 = samples
                validate_samples(samples)
                # Two-sample Z-test
                z_stat, p_value = stats.ztest(sample1, sample2, alternative='two-sided')
                return jsonify({
                    "z_statistic": float(z_stat),
                    "p_value": float(p_value),
                    "message": "Two-sample Z-test performed."
                })
            else:
                return jsonify({"error": "Invalid number of samples. Expected 1 or 2."}), 400
        else:
            return jsonify({"error": "Missing 'samples' key in data."}), 400
    except Exception as e:
        return jsonify({"error": str(e)}), 500

