@app.route('/outliertest', methods=['POST'])
def outliertest():
    try:
        data = request.get_json()
        if not data:
            return jsonify({"error": "No data provided."}), 400

        if "samples" in data:
            samples = data["samples"]
            validate_outliers(samples)
            # Using IQR method
            q1 = np.percentile(samples[0], 25)
            q3 = np.percentile(samples[0], 75)
            iqr = q3 - q1
            lower_bound = q1 - 1.5 * iqr
            upper_bound = q3 + 1.5 * iqr
            outliers = [x for x in samples[0] if x < lower_bound or x > upper_bound]
            return jsonify({
