## 🧪 Unit Tests

```python
import unittest
from unittest.mock import patch, MagicMock
from your_module import PuppetStateLoader, PuppetChecksumPlugin, verify_package_hook

class TestPuppetChecksumPlugin(unittest.TestCase):
    def setUp(self):
        self.puppet_state_path = "/path/to/puppet_state.yaml"
        self.loader = PuppetStateLoader(self.puppet_state_path)
        self.loader.state = {
            "File[/path/to/example-package]": {
                "checksums": {
                    "md5": "d41d8cd98f00b204e9800998ecf8427e"
                }
            }
        }

    @patch("builtins.open", new_callable=MagicMock)
    def test_load_puppet_state(self, mock_open):
        mock_open.return_value.__enter__.return_value.read.return_value = yaml.dump(self.loader.state)
        self.assertTrue(self.loader.load())

    def test_get_checksum(self):
        file_path = "File[/path/to/example-package]"
        self.assertEqual(self.loader.get_checksum(file_path), "d41d8cd98f00b204e9800998ecf8427e")

    def test_verify_package_hook(self):
        plugin = PuppetChecksumPlugin(self.puppet_state_path)
        plugin.loader.state = {
            "File[/path/to/example-package]": {
                "checksums": {
                    "md5": "d41d8cd98f00b204e9800998ecf8427e"
                }
            }
        }
        result = plugin.verify_package_hook("example-package")
        self.assertEqual(result['expected_checksum'], "d41d8cd98f00b204e9800998ecf8427e")
        self.assertEqual(result['actual_checksum'], "d41d8cd98f00b204e9800998ecf8427e")
        self.assertTrue(result['is_match'])

    def test_verify_package_hook_no_checksum(self):
        plugin = PuppetChecksumPlugin(self.puppet_state_path)
        plugin.loader.state = {}
        result = plugin.verify_package_hook("example-package")
        self.assertEqual(result['error'], "No checksum found in Puppet state for this package")

    def test_config_hook(self):
        plugin = PuppetChecksumPlugin(self.puppet_state_path)
        config = {'puppet_state_path': '/new/path/to/puppet_state.yaml'}
        plugin.config_hook(config)
        self.assertEqual(plugin.loader.puppet_state_path, '/new/path/to/puppet_state.yaml')

if __name__ == "__main__":
    unittest.main()
```

