```python
class Solution:
    def backspace_compare(self, str1: str, str2: str) -> bool:
        # Helper function to process a string and return the final string after applying backspaces
        def process_string(s: str) -> str:
            result = []
            for char in s:
                if char == '#':
                    if result:
                        result.pop()
                else:
                    result.append(char)
            return ''.join(result)

        return process_string(str1) == process_string(str2)
```

### ✅ **Unit Tests**

```python
import unittest

class TestBackspaceCompare(unittest.TestCase):
    def setUp(self):
        self.sol = Solution()

    def test_equal_after_backspaces(self):
        self.assertTrue(self.sol.backspace_compare("ab##", "c#d#"))  # "ab##" -> "a", "c#d#" -> "a" → True
        self.assertTrue(self.sol.backspace_compare("a##c", "#a#c"))  # "a##c" -> "c", "#a#c" -> "c" → True
        self.assertFalse(self.sol.backspace_compare("a#c", "b"))     # "a#c" -> "a", "b" -> "b" → False

    def test_empty_strings(self):
        self.assertTrue(self.sol.backspace_compare("", ""))         # Both empty → True
        self.assertTrue(self.sol.backspace_compare("", "##"))       # "##" → "" → True
        self.assertTrue(self.sol.backspace_compare("##", ""))       # "##" → "" → True

    def test_only_backspaces(self):
        self.assertTrue(self.sol.backspace_compare("####", "####"))  # Both become empty → True
        self.assertTrue(self.sol.backspace_compare("##a#", "##a#")) # Both become "a" → True

    def test_mixed_characters_and_backspaces(self):
        self.assertTrue(self.sol.backspace_compare("a#b#c", "a#b#c"))  # Both become "ab" → True
        self.assertFalse(self.sol.backspace_compare("a#b#c", "a#b#d")) # "ab" vs "ab" → False

    def test_backspace_at_start(self):
        self.assertTrue(self.sol.backspace_compare("#a", "a"))       # "#a" → "a", "a" → "a" → True
        self.assertTrue(self.sol.backspace_compare("#a#", "a"))      # "#a#" → "a", "a" → "a" → True

    def test_backspace_with_no_characters(self):
        self.assertTrue(self.sol.backspace_compare("#", "#"))        # Both become empty → True
        self.assertTrue(self.sol.backspace_compare("#", "##"))       # Both become empty → True

if __name__ == '__main__':
    unittest.main()
