    except Exception as e:
        click.echo(f"Error: {e}")

@cli.command()
@click.argument("evaluation", type=click.File('r'))
def summary(evaluation):
    """Print a summary of an evaluation from a file."""
    try:
        data = evaluation.read()
        evaluation_data = eval(data)
        print_summary(evaluation_data)
    except Exception as e:
        click.echo(f"Error: {e}")

