```python
from typing import List 

class Solution:
    def __init__(self):
        self.dirs = [[0, 1], [1, 0], [0, -1], [-1, 0]]
        self.visited = set()

    @staticmethod
    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def dfs(self, source, target, cur):
        if cur == target:
            return True
        if self.manhattan(source, cur) > 200:
            return True
        cur_tuple = (cur[0], cur[1])
        self.visited.add(cur_tuple)
        for d in self.dirs:
            new_cur = [cur[0] + d[0], cur[1] + d[1]]
            if 0 <= new_cur[0] < 1e6 and 0 <= new_cur[1] < 1e6:
                new_cur_tuple = (new_cur[0], new_cur[1])
                if new_cur_tuple not in self.visited and new_cur not in self.blocked:
                    if self.dfs(source, target, new_cur):
                        return True
        return False

    def isEscapePossible(self, blocked: List[List[int]], source: List[int], target: List[int]) -> bool:
        self.blocked = {tuple(point) for point in blocked}
        if self.dfs(source, target, source):
            self.visited.clear()
            if self.dfs(target, source, target):
                return True
        return False

# Test cases to verify the solution
if __name__ == "__main__": 
    # Test case 1
    blocked = [[0,3],[1,0],[1,1],[1,2],[1,3]]
    source = [0,0]
    target = [0,2]
    s = Solution()
    assert s.isEscapePossible(blocked, source, target) == True, "Test case 1 failed"

    # Test case 2
    blocked = [[0,1],[1,0],[1,1],[1,2],[1,3],[2,3],[3,1],[3,2]]
    source = [0,0]
    target = [3,3]
    assert s.isEscapePossible(blocked, source, target) == False, "Test case 2 failed"

    # Test case 3
    blocked = []
    source = [0,0]
    target = [999999,999999]
    assert s.isEscapePossible(blocked, source, target) == True, "Test case 3 failed"

    print("All test cases passed!")
```

In this solution, we use a depth-first search (DFS) algorithm to explore the grid from the source to the target. We use a set to keep track of visited cells to avoid cycles and to ensure we do not revisit cells. The `manhattan` static method is used to calculate the Manhattan distance between two cells, which is used to determine if we have moved too far from the source. The `isEscapePossible` method initializes the blocked cells as a set for efficient lookup and then performs two DFS searches: one from the source to the target and another from the target to the source. If both searches succeed, the function returns `True`, indicating that escape is possible.

