```python
from flask import Flask, render_template, request, jsonify
import multiprocessing
import os
import time
from utils.acronym_utils import load_dictionary, genAcronym

app = Flask(__name__)
DICTIONARY_PATH = 'words.txt'
dictionary = None

def load_dict():
    global dictionary
    try:
        dictionary = load_dictionary(DICTIONARY_PATH)
    except FileNotFoundError:
        dictionary = None

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/generate', methods=['POST'])
def generate():
    phrase = request.form['phrase'].lower()
    clip = int(request.form['clip'])
    words = phrase.split()
    if not words:
        return jsonify({"error": "Please enter a phrase."})

    # Load dictionary if not already loaded
    if not dictionary:
        load_dict()

    # Use multiprocessing to generate acronym in the background
    result = multiprocessing.Queue()
    process = multiprocessing.Process(
        target=genAcronym,
        args=(words, clip, dictionary),
        daemon=True
    )
    process.start()
    process.join(timeout=5)  # Wait up to 5 seconds

    if process.is_alive():
        process.terminate()
        process.join()
        return jsonify({"error": "Generation timed out."})

    acronym, components, processed, valid = result.get()
    return jsonify({
        "acronym": acronym,
        "components": components,
        "processed": processed,
        "valid": valid
    })

if __name__ == '__main__':
    app.run(debug=True)
