        "darkslateblue", "darkslategray", "darkslategrey", "darkturquoise", "darkviolet", "deeppink", "deepskyblue",
        "dimgray", "dimgrey", "dodgerblue", "firebrick", "floralwhite", "forestgreen", "fuchsia", "gainsboro", "ghostwhite",
        "gold", "goldenrod", "gray", "green", "greenyellow", "honeydew", "hotpink", "indianred", "indigo", "ivory",
        "khaki", "lavender", "lavenderblush", "lawngreen", "lemonchiffon", "lightblue", "lightcoral", "lightcyan",
        "lightgoldenrodyellow", "lightgray", "lightgreen", "lightgrey", "lightpink", "lightsalmon", "lightseagreen",
        "lightskyblue", "lightslategray", "lightslategrey", "lightsteelblue", "lightyellow", "lime", "limegreen",
        "linen", "magenta", "maroon", "mediumaquamarine", "mediumblue", "mediumorchid", "mediumpurple", "mediumseagreen",
        "mediumslateblue", "mediumspringgreen", "mediumturquoise", "mediumvioletred", "midnightblue", "mintcream",
        "mistyrose", "moccasin", "navajowhite", "navy", "oldlace", "olive", "olivedrab", "orange", "orangered",
        "orchid", "palegoldenrod", "palegreen", "paleturquoise", "palevioletred", "papayawhip", "peachpuff", "peru",
        "pink", "plum", "powderblue", "purple", "rebeccapurple", "red", "rosybrown", "royalblue", "saddlebrown",
        "salmon", "sandybrown", "seagreen", "seashell", "sienna", "silver", "skyblue", "slateblue", "slategray",
        "slategrey", "snow", "springgreen", "steelblue", "tan", "teal", "thistle", "tomato", "turquoise", "violet",
        "wheat", "white", "whitesmoke", "yellow", "yellowgreen"
    }
    if color.lower() in named_colors:
        return True

    # Check for hex color codes (e.g., #FFFFFF, #000000, #00ff00)
    hex_pattern = re.compile(r'^#([A-Fa-f0-9]{6})$')
    if hex_pattern.match(color):
        return True

    # Check for 3-digit hex color codes (e.g., #000, #fff)
    hex_pattern_3 = re.compile(r'^#([A-Fa-f0-9]{3})$')
    if hex_pattern_3.match(color):
        return True

    return False

@register
class ColorPicker(DescriptionWidget, ValueWidget, CoreWidget):
    def __init__(
        self,
        value: str = "black",
        concise: bool = False,
        disabled: bool = False,
        _view_name: str = "ColorPickerView",
        _model_name: str = "ColorPickerModel"
    ):
        super().__init__(description="The color value.")
        ValueWidget.__init__(self, value=value)
        CoreWidget.__init__(self, disabled=disabled)

        self.concise = concise
        self._view_name = _view_name
        self._model_name = _model_name
        self.sync = True  # Tag to indicate synchronization with frontend

        # Validate the initial value
        self.value = value  # This will trigger the setter

    @property
    def value(self) -> str:
        return self._value

    @value.setter
    def value(self, new_value: str):
        if not is_valid_color(new_value):
            raise ValueError(f"Invalid color format: {new_value}")
        self._value = new_value

    @property
    def concise(self) -> bool:
        return self._concise

    @concise.setter
    def concise(self, new_value: bool):
        self._concise = new_value

    @property
    def disabled(self) -> bool:
        return self._disabled

    @disabled.setter
    def disabled(self, new_value: bool):
        self._disabled = new_value

    @property
    def _view_name(self) -> str:
        return self._view_name

    @_view_name.setter
