```python
import unittest

class TestColorPicker(unittest.TestCase):
    def test_valid_color(self):
        cp = ColorPicker(value="red")
        self.assertEqual(cp.value, "red")
        self.assertEqual(cp._view_name, "ColorPickerView")
        self.assertEqual(cp._model_name, "ColorPickerModel")
        self.assertTrue(cp.sync)
        self.assertFalse(cp.disabled)
        self.assertFalse(cp.concise)

    def test_invalid_color(self):
        with self.assertRaises(ValueError):
            ColorPicker(value="invalid_color")

    def test_hex_color(self):
        cp = ColorPicker(value="#FFFFFF")
        self.assertEqual(cp.value, "#FFFFFF")

    def test_hex_color_3_digits(self):
        cp = ColorPicker(value="#000")
        self.assertEqual(cp.value, "#000")

    def test_named_color(self):
        cp = ColorPicker(value="blue")
        self.assertEqual(cp.value, "blue")

    def test_setter_valid_color(self):
        cp = ColorPicker(value="black")
        cp.value = "green"
        self.assertEqual(cp.value, "green")

    def test_setter_invalid_color(self):
        cp = ColorPicker(value="black")
        with self.assertRaises(ValueError):
            cp.value = "invalid"

    def test_concise(self):
        cp = ColorPicker(concise=True)
        self.assertTrue(cp.concise)

    def test_disabled(self):
        cp = ColorPicker(disabled=True)
        self.assertTrue(cp.disabled)

    def test_default_values(self):
        cp = ColorPicker()
        self.assertEqual(cp.value, "black")
        self.assertFalse(cp.concise)
        self.assertFalse(cp.disabled)

    def test_custom_view_model_names(self):
        cp = ColorPicker(_view_name="CustomView", _model_name="CustomModel")
        self.assertEqual(cp._view_name, "CustomView")
        self.assertEqual(cp._model_name, "CustomModel")

if __name__ == "__main__":
    unittest.main()
