from datetime import datetime
from typing import Dict, Any, Optional
import util  # Assuming this module contains the required utility functions

class Tweets:
    def __init__(self, tweets: Dict[int, Dict[str, Any]]):
        self.tweets = {}
        for tweet_id, tweet_data in tweets.items():
            self.add_tweet(tweet_id, tweet_data)

    def add_tweet(self, tweet_id: int, tweet_data: Dict[str, Any]):
        if not isinstance(tweet_id, int):
            raise ValueError("Tweet ID must be an integer.")
        if not isinstance(tweet_data, dict):
            raise ValueError("Tweet data must be a dictionary.")

        required_keys = ['text', 'created_at', 'user_id']
        for key in required_keys:
            if key not in tweet_data:
                raise KeyError(f"Missing required key '{key}' in tweet data.")

        if not isinstance(tweet_data['text'], str) or not tweet_data['text']:
            raise ValueError("Tweet text must be a non-empty string.")

        try:
            self.tweets[tweet_id] = {
                'id': tweet_id,
                'text': tweet_data['text'],
                'created_at': datetime.fromisoformat(tweet_data['created_at']),
                'user_id': tweet_data['user_id']
            }
        except ValueError as e:
            raise ValueError(f"Invalid date format for created_at: {e}")

    @classmethod
    def from_dict(cls, data: Dict[int, Dict[str, Any]]) -> 'Tweets':
        if not isinstance(data, dict):
            raise TypeError("Input data must be a dictionary.")

        if not all(isinstance(k, int) for k in data.keys()):
            raise TypeError("Tweet IDs must be integers.")

        if not all(isinstance(v, dict) for v in data.values()):
            raise TypeError("Tweet data must be dictionaries.")

        return cls(data)

    def to_dict(self) -> Dict[int, Dict[str, Any]]:
        return {
            tweet_id: {
                'text': tweet['text'],
                'created_at': tweet['created_at'].isoformat(),
                'user_id': tweet['user_id']
            }
            for tweet_id, tweet in self.tweets.items()
        }

    def __repr__(self):
        return f"Tweets({self.tweets})"
