        self.filters = filters
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding

    def to_dict(self):
        return {
            "type": "Convolution",
            "input_shape": self.input_shape,
            "filters": self.filters,
            "kernel_size": self.kernel_size,
            "stride": self.stride,
            "padding": self.padding
        }

