    def from_dict(cls, d):
        if "type" not in d or d["type"] != "Convolution" or "input_shape" not in d or "filters" not in d or "kernel_size" not in d:
            raise ValueError("Invalid Convolution layer dictionary")
        return cls(
            d["input_shape"],
            d["filters"],
            d["kernel_size"],
            d.get("stride", 1),
            d.get("padding", 0)
        )

    def get_output_shape(self):
