        in_h, in_w, in_c = self.input_shape
        k_h, k_w = self.kernel_size
        s = self.stride
        p = self.padding

        out_h = (in_h + 2 * p - k_h) // s + 1
        out_w = (in_w + 2 * p - k_w) // s + 1
        out_c = self.filters
        return (out_h, out_w, out_c)

    def get_output_size(self):
